const row = $json;
const nombre = (row['Nombre completo'] || '').toString().trim();
const email = (row['Correo electrónico'] || '').toString().trim();
const categoria = (row['Categoría del problema'] || '').toString().trim();
const mensaje = (row['Describe tu problema'] || '').toString().trim();
const marcaTemporalRaw = row['Marca temporal'] || new Date().toISOString();

// Parseo defensivo: Google Forms/Sheets en español exporta DD/M/YYYY H:mm:ss
// (día y mes sin cero a la izquierda), que no es ISO y Airtable/Luxon no puede
// interpretar solo. Lo convertimos acá, una sola vez, para toda la ejecución.
function parseMarcaTemporal(raw) {
  const s = String(raw).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
    const d = new Date(s);
    if (!isNaN(d.getTime())) return d;
  }
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T]?(\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (m) {
    const [, dd, mm, yyyy, hh, min, ss] = m;
    return new Date(Number(yyyy), Number(mm) - 1, Number(dd), Number(hh), Number(min), Number(ss || 0));
  }
  const fallback = new Date(s);
  return isNaN(fallback.getTime()) ? null : fallback;
}

const marcaTemporalParsed = parseMarcaTemporal(marcaTemporalRaw);
const marcaTemporalISO = marcaTemporalParsed ? marcaTemporalParsed.toISOString() : null;

// ID determinístico (evita duplicados si el trigger reprocesa la misma fila)
// OJO: usa el string crudo (marcaTemporalRaw), igual que siempre, para no
// cambiar el ticket_id de filas que ya se procesaron antes de este fix.
const base = (email + '|' + marcaTemporalRaw + '|' + mensaje).toLowerCase();
let hash = 0;
for (let i = 0; i < base.length; i++) {
  hash = (hash * 31 + base.charCodeAt(i)) >>> 0;
}
const ticket_id = 'TCK-' + hash;

return {
  ticket_id,
  ticket_nombre: nombre,
  ticket_email: email,
  ticket_categoria: categoria,
  ticket_mensaje: mensaje,
  ticket_marca_temporal: marcaTemporalRaw,
  ticket_marca_temporal_iso: marcaTemporalISO,
};

return {
  ticket_id: $json.ticket_id || 'N/A',
  nodo_origen: 'IF - Datos Completos',
  tipo_error: 'Validación fallida',
  detalle_error: 'Faltan datos obligatorios en el ticket (email, mensaje o categoría vacíos).',
};

const errMsg = ($json.error && ($json.error.message || $json.error)) || 'Error desconocido';
let tipo = 'API Error';
if (/rate.?limit/i.test(errMsg)) tipo = 'Rate limit';
else if (/timeout/i.test(errMsg)) tipo = 'Timeout';

return {
  ticket_id: $('Code - Normalizar Datos').first().json.ticket_id,
  nodo_origen: 'Airtable - Crear Ticket',
  tipo_error: tipo,
  detalle_error: errMsg.toString().slice(0, 500),
};

const errMsg = ($json.error && ($json.error.message || $json.error)) || 'Error desconocido';
let tipo = 'API Error';
if (/rate.?limit/i.test(errMsg)) tipo = 'Rate limit';
