const resp = $json;
let text = '';
try { text = resp.content[0].text; } catch (e) { text = '{}'; }
let parsed = {};
try {
  const match = text.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : text);
} catch (e) {
  parsed = { categoria_ia: 'Otro', urgencia_ia: 'Media' };
}
return {
  categoria_ia: parsed.categoria_ia || 'Otro',
  urgencia_ia: parsed.urgencia_ia || 'Media',
};

const errMsg = ($json.error && ($json.error.message || $json.error)) || 'Error desconocido';
let tipo = 'API Error';
if (/rate.?limit/i.test(errMsg)) tipo = 'Rate limit';
