}
return {
  respuesta_ia: parsed.respuesta || 'Gracias por tu mensaje. Nuestro equipo de soporte lo está revisando y te responderá a la brevedad.',
};

const errMsg = ($json.error && ($json.error.message || $json.error)) || 'Error desconocido';
