const errMsg = ($json.error && ($json.error.message || $json.error)) || 'Error desconocido';
let tipo = 'API Error';
if (/rate.?limit/i.test(errMsg)) tipo = 'Rate limit';
else if (/timeout/i.test(errMsg)) tipo = 'Timeout';

return {
  ticket_id: $('Code - Normalizar Datos').item.json.ticket_id,
  nodo_origen: 'Airtable - Buscar Duplicado',
  tipo_error: tipo,
  detalle_error: errMsg.toString().slice(0, 500),
};

const categorias = ($vars.CATEGORIAS_TICKET || '').split(',').map(s => s.trim()).filter(Boolean);
const urgencias = ($vars.URGENCIAS_TICKET || '').split(',').map(s => s.trim()).filter(Boolean);
const ticket = $('Set - Consolidar Ticket').item.json;

const prompt = 'Sos un clasificador de tickets de soporte para ' + $vars.COMPANY_NAME + '.\n' +
  'Categorías válidas: ' + categorias.join(', ') + '.\n' +
  'Niveles de urgencia válidos: ' + urgencias.join(', ') + '.\n\n' +
  'Ticket del cliente:\n' +
  'Categoría declarada por el cliente: ' + ticket.ticket_categoria + '\n' +
  'Mensaje: "' + ticket.ticket_mensaje + '"\n\n' +
  'Devolvé ÚNICAMENTE un JSON válido con este formato exacto, sin texto adicional:\n' +
  '{"categoria_ia": "<una de las categorías válidas>", "urgencia_ia": "<uno de los niveles válidos>"}';

return {
  anthropic_body: {
    model: $vars.CLAUDE_HAIKU_MODEL,
    max_tokens: Number($vars.CLAUDE_MAX_TOKENS_CLASIFICACION),
    messages: [{ role: 'user', content: prompt }],
  },
};

const ticket = $('Set - Consolidar Ticket').first().json;
const clasificacion = $('Code - Parsear Clasificacion').first().json;

const faqItems = $input.all().map(item => item.json.fields || {}).filter(f => f['Pregunta']);
const kb = faqItems.map(f => '- ' + f['Categoría'] + ' | ' + f['Pregunta'] + ': ' + f['Respuesta']).join('\n');

const systemText = 'Sos un agente de atención al cliente de ' + $vars.COMPANY_NAME + '. Redactá una respuesta breve, empática y profesional en español para el ticket de soporte que se te va a pasar. No inventes información que no tengas (números de pedido, fechas de entrega, montos) — si hace falta ese dato, pedíselo al cliente o indicá que el equipo lo revisará.\n\n' +
  'Base de conocimiento de referencia:\n' + kb + '\n\n' +
  'Devolvé ÚNICAMENTE un JSON válido con este formato exacto, sin texto adicional:\n' +
  '{"respuesta": "<el texto de la respuesta al cliente>"}';

const userText = 'Nombre del cliente: ' + ticket.ticket_nombre + '\n' +
  'Categoría: ' + clasificacion.categoria_ia + '\n' +
  'Urgencia: ' + clasificacion.urgencia_ia + '\n' +
  'Mensaje del cliente: "' + ticket.ticket_mensaje + '"';

return [{
  json: {
    anthropic_body: {
      model: $vars.CLAUDE_SONNET_MODEL,
      max_tokens: Number($vars.CLAUDE_MAX_TOKENS_RESPUESTA),
      system: [
        { type: 'text', text: systemText, cache_control: { type: 'ephemeral' } }
      ],
      messages: [{ role: 'user', content: userText }],
    },
  },
}];

const errMsg = ($json.error && ($json.error.message || $json.error)) || 'Error desconocido';
let tipo = 'API Error';
if (/rate.?limit/i.test(errMsg)) tipo = 'Rate limit';
else if (/timeout/i.test(errMsg)) tipo = 'Timeout';

return {
  ticket_id: $('Code - Normalizar Datos').item.json.ticket_id,
  nodo_origen: 'Airtable - Update Procesado IA',
  tipo_error: tipo,
  detalle_error: errMsg.toString().slice(0, 500),
};

const usage = $json.usage || {};
const ticket = $('Set - Consolidar Ticket').first().json;

const inputTokens = usage.input_tokens || 0;
const outputTokens = usage.output_tokens || 0;

const precioInput = Number($vars.PRECIO_HAIKU_INPUT) / 1000000;
const precioOutput = Number($vars.PRECIO_HAIKU_OUTPUT) / 1000000;

const costoReal = (inputTokens * precioInput) + (outputTokens * precioOutput);

return {
  json: {
    ticket_id: ticket.ticket_id,
    tarea: 'Clasificación',
    modelo: $vars.CLAUDE_HAIKU_MODEL,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    cache_creation_input_tokens: 0,
    cache_read_input_tokens: 0,
    uso_rag: false,
    costo_real_usd: Number(costoReal.toFixed(6)),
    costo_sin_caching_usd: Number(costoReal.toFixed(6)),
    ahorro_caching_usd: 0,
    ahorro_caching_pct: 0,
  },
};

const usage = $json.usage || {};
const ticket = $('Set - Consolidar Ticket').first().json;

const inputTokens = usage.input_tokens || 0;
const outputTokens = usage.output_tokens || 0;
const cacheWriteTokens = usage.cache_creation_input_tokens || 0;
const cacheReadTokens = usage.cache_read_input_tokens || 0;

const precioInput = Number($vars.PRECIO_SONNET_INPUT) / 1000000;
const precioOutput = Number($vars.PRECIO_SONNET_OUTPUT) / 1000000;
const precioCacheWrite = Number($vars.PRECIO_SONNET_CACHE_WRITE) / 1000000;
const precioCacheRead = Number($vars.PRECIO_SONNET_CACHE_READ) / 1000000;

const costoReal = (inputTokens * precioInput)
  + (cacheWriteTokens * precioCacheWrite)
  + (cacheReadTokens * precioCacheRead)
  + (outputTokens * precioOutput);

const costoSinCaching = ((inputTokens + cacheWriteTokens + cacheReadTokens) * precioInput)
  + (outputTokens * precioOutput);

const ahorroUsd = costoSinCaching - costoReal;
const ahorroPct = costoSinCaching > 0 ? (ahorroUsd / costoSinCaching) * 100 : 0;

return {
  json: {
    ticket_id: ticket.ticket_id,
    tarea: 'Redacción',
    modelo: $vars.CLAUDE_SONNET_MODEL,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    cache_creation_input_tokens: cacheWriteTokens,
    cache_read_input_tokens: cacheReadTokens,
    uso_rag: (cacheWriteTokens + cacheReadTokens) > 0,
    costo_real_usd: Number(costoReal.toFixed(6)),
    costo_sin_caching_usd: Number(costoSinCaching.toFixed(6)),
    ahorro_caching_usd: Number(ahorroUsd.toFixed(6)),
    ahorro_caching_pct: Number(ahorroPct.toFixed(2)),
  },
};

// El paso anterior (Buscar/Crear la tupla del día en Panel KPIs) devolvió
// el registro de Panel KPIs, no los tickets originales. Ese registro solo
// sirve para que 'Merge - Tupla de Fecha (KPIs)' quede disponible como
// referencia (via $('Merge - Tupla de Fecha (KPIs)')) mas adelante en el
// loop. Acá recuperamos los items reales que entraron por el Trigger,
// para que el Loop itere sobre los tickets de verdad y no sobre la tupla de KPIs.
return $('Trigger - Nuevo Reclamo o Consulta').all();
